import json, csv
with open('json/event.json') as f: events = {r['event_id']: r['event_name'] for r in json.load(f)['records']}
with open('json/expense.json') as f: expenses = json.load(f)['records']
with open('csv/budget.csv') as f: budgets = {r['budget_id']: r['link_to_event'] for r in csv.DictReader(f)}
costs = {}
for e in expenses:
  bid = e.get('link_to_budget')
  if bid and bid in budgets:
    eid = budgets[bid]
    costs[eid] = costs.get(eid, 0) + float(e['cost'])
min_cost = min(costs.values())
lowest = [(events.get(eid, eid), c) for eid, c in costs.items() if c == min_cost]
print(f'Minimum cost: {min_cost}')
for name, c in lowest:
  print(f'{name}: {c}')

